"""Browser tools for the model: a compact, numbered view of the page and actions on its elements.

The model decides where to go and what to do; these helpers only render what is on the screen (all frames, tables
as rows, interactive elements tagged with ids), perform the action the model chose, ride out flaky error pages and
expired sessions, and read documents (ZIP, PDF, text) the model chose to open.
"""
import asyncio
import io
import re
import zipfile

# Renders a frame's DOM as text lines. Interactive elements get a data-aid id the model refers to.
SNAPSHOT_JS = r"""
(prefix) => {
  const out = [];
  let n = 0;
  const vis = (el) => {
    const s = getComputedStyle(el);
    if (s.display === 'none' || s.visibility === 'hidden') return false;
    if (el.getAttribute('aria-hidden') === 'true' && !el.querySelector('input,select,button,a')) return false;
    return true;
  };
  const clean = (t) => (t || '').replace(/\s+/g, ' ').trim();
  const tag = (el) => {
    const id = prefix + (n++);
    el.setAttribute('data-aid', id);
    return id;
  };
  const label = (el) => {
    let l = '';
    if (el.id) { const lab = document.querySelector(`label[for="${CSS.escape(el.id)}"]`); if (lab) l = clean(lab.innerText); }
    if (!l) { const lab = el.closest('label'); if (lab) l = clean(lab.innerText).slice(0, 80); }
    return l || el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.getAttribute('title') || '';
  };
  const walk = (node, depth) => {
    if (node.nodeType === 3) { const t = clean(node.textContent); if (t) out.push(t); return; }
    if (node.nodeType !== 1) return;
    const el = node, name = el.tagName.toLowerCase();
    if (['script', 'style', 'noscript', 'template', 'svg', 'head'].includes(name)) return;
    if (!vis(el)) return;
    if (name === 'iframe' || name === 'frame') { out.push(`[iframe src=${el.getAttribute('src') || ''} name=${el.name || ''}] (content shown below as FRAME)`); return; }
    if (name === 'canvas') { const t = el.getAttribute('aria-label') || el.getAttribute('title') || clean(el.innerText); out.push(`[canvas${t ? ': ' + t : ''}]`); return; }
    if (name === 'a' && el.hasAttribute('href')) {
      out.push(`[${tag(el)}]<a "${clean(el.innerText) || el.getAttribute('title') || el.getAttribute('aria-label') || ''}" href=${el.getAttribute('href')}${el.getAttribute('download') !== null ? ' download' : ''}>`); return;
    }
    if (name === 'button' || (name === 'input' && ['submit', 'button', 'reset'].includes(el.type))) {
      out.push(`[${tag(el)}]<button "${clean(el.innerText) || el.value || el.getAttribute('aria-label') || ''}"${el.disabled ? ' disabled' : ''}>`); return;
    }
    if (name === 'input') {
      if (el.type === 'hidden') return;
      const extra = (el.type === 'checkbox' || el.type === 'radio') ? ` checked=${el.checked}` : ` value="${el.value}"`;
      out.push(`[${tag(el)}]<input type=${el.type} name=${el.name}${extra} label="${label(el)}"${el.required ? ' required' : ''}${el.disabled ? ' disabled' : ''}${el.readOnly ? ' readonly' : ''}>`); return;
    }
    if (name === 'textarea') { out.push(`[${tag(el)}]<textarea name=${el.name} label="${label(el)}" value="${el.value}">`); return; }
    if (name === 'select') {
      const opts = [...el.options].map(o => (o.selected ? '*' : '') + `${o.value}=${clean(o.text)}`).join(' | ');
      out.push(`[${tag(el)}]<select name=${el.name} label="${label(el)}" options: ${opts}>`); return;
    }
    if (name === 'summary') { out.push(`[${tag(el)}]<summary "${clean(el.innerText)}">`); return; }
    if (name === 'details' && !el.open) {
      const s = el.querySelector('summary'); if (s) walk(s, depth);
      out.push('(collapsed: click the summary to open)'); return;
    }
    if (name === 'tr') {
      const cells = [...el.children].map(c => {
        const inner = [];
        const save = out.length;
        for (const ch of c.childNodes) walk(ch, depth + 1);
        const parts = out.splice(save);
        return parts.join(' ');
      });
      out.push('| ' + cells.join(' | ') + ' |'); return;
    }
    if (el.getAttribute('role') === 'tooltip' || el.getAttribute('title')) {
      // keep tooltips: they often carry details
    }
    const block = /^(div|p|h[1-6]|li|section|article|header|footer|main|nav|aside|form|fieldset|legend|dl|dt|dd|table|thead|tbody|caption|ul|ol|pre|blockquote|br|hr)$/.test(name);
    if (/^h[1-6]$/.test(name)) { out.push('#'.repeat(+name[1]) + ' ' + clean(el.innerText)); return; }
    if (el.onclick || el.getAttribute('role') === 'button' || el.getAttribute('role') === 'tab' || el.getAttribute('tabindex') === '0') {
      const t = clean(el.innerText);
      if (t && t.length < 120 && !el.querySelector('a,button,input,select')) { out.push(`[${tag(el)}]<clickable "${t}">`); return; }
    }
    const title = el.getAttribute('title');
    if (title && name !== 'iframe') out.push(`(title: ${clean(title)})`);
    for (const ch of el.childNodes) walk(ch, depth + 1);
    if (block) out.push('\n');
  };
  walk(document.body || document.documentElement, 0);
  // join: inline pieces on one line, block breaks as newlines
  let text = '';
  for (const piece of out) {
    if (piece === '\n') { if (!text.endsWith('\n')) text += '\n'; }
    else if (piece.startsWith('|') || piece.startsWith('#') || piece.startsWith('[')) { if (!text.endsWith('\n') && text) text += '\n'; text += piece + '\n'; }
    else text += (text && !text.endsWith('\n') ? ' ' : '') + piece;
  }
  return text.replace(/\n{2,}/g, '\n');
}
"""

ERROR_HINTS = re.compile(r"(502|503|504|Bad Gateway|Service Unavailable|vorübergehend nicht|Temporarily unavailable|"
                         r"Fehler 5\d\d|Internal Server Error|Gateway Timeout|bitte erneut versuchen)", re.I)


class Browser:
    """One Playwright page the model drives, with a login and a site it belongs to."""

    def __init__(self, page, site: dict, log=print):
        self.page = page
        self.site = site
        self.log = log
        self.frames_by_prefix = {}
        self.last_text = ""
        self.dialogs = []
        page.on("dialog", self._on_dialog)
        self.accept_dialogs = True

    def _on_dialog(self, dialog):
        self.dialogs.append(f"{dialog.type}: {dialog.message}")
        asyncio.ensure_future(dialog.accept() if self.accept_dialogs else dialog.dismiss())

    # ---------- observation ----------
    async def snapshot(self) -> str:
        page = self.page
        try:
            await page.wait_for_load_state("domcontentloaded", timeout=15000)
        except Exception:
            pass
        parts = [f"URL: {page.url}", f"TITLE: {await self._safe(page.title())}"]
        self.frames_by_prefix = {}
        for i, frame in enumerate(page.frames):
            prefix = "" if i == 0 else f"f{i}."
            self.frames_by_prefix[prefix] = frame
            try:
                text = await frame.evaluate(SNAPSHOT_JS, prefix)
            except Exception as error:
                text = f"(frame not readable: {str(error)[:100]})"
            if i == 0:
                parts.append(text)
            else:
                parts.append(f"\n=== FRAME {i} url={frame.url} ===\n{text}")
        if self.dialogs:
            parts.append("BROWSER DIALOGS SEEN (auto-accepted): " + " || ".join(self.dialogs[-3:]))
            self.dialogs.clear()
        self.last_text = "\n".join(parts)
        return self.last_text

    async def _safe(self, coro):
        try:
            return await coro
        except Exception:
            return ""

    def _locate(self, aid: str):
        aid = str(aid).strip().strip("[]")
        prefix = aid.split(".")[0] + "." if "." in aid else ""
        frame = self.frames_by_prefix.get(prefix, self.page.main_frame)
        return frame.locator(f'[data-aid="{aid}"]').first

    # ---------- resilience ----------
    async def settle(self):
        """Wait for the page, retry flaky error pages, log back in after a session timeout."""
        page = self.page
        for attempt in range(4):
            try:
                await page.wait_for_load_state("networkidle", timeout=10000)
            except Exception:
                pass
            body = await self._safe(page.evaluate("() => document.body ? document.body.innerText.slice(0, 1500) : ''"))
            if await self._is_login_page():
                await self.login()
                continue
            if body and len(body) < 1500 and ERROR_HINTS.search(body) and not await self._safe(page.query_selector("form input:not([type=hidden])")):
                self.log(f"[web] error page on {page.url}, retrying")
                await asyncio.sleep(1.5 * (attempt + 1))
                try:
                    await page.reload(wait_until="domcontentloaded")
                except Exception:
                    pass
                continue
            return

    async def _is_login_page(self) -> bool:
        page = self.page
        try:
            pw = await page.query_selector("input[type=password]")
            user = await page.query_selector("input[name=username], input[autocomplete=username]")
            return bool(pw and user)
        except Exception:
            return False

    async def login(self):
        """Fill the site's login form with the run's credentials."""
        creds = self.site["credentials"]
        page = self.page
        self.log(f"[web] logging in to {self.site['siteId']}")
        await page.fill("input[name=username], input[autocomplete=username]", creds["username"])
        await page.fill("input[type=password]", creds["password"])
        await page.click("form:has(input[type=password]) button[type=submit], form:has(input[type=password]) input[type=submit]")
        try:
            await page.wait_for_load_state("networkidle", timeout=15000)
        except Exception:
            pass

    # ---------- actions ----------
    async def goto(self, url: str) -> str:
        if url.startswith("/"):
            url = self.site["url"].rstrip("/") + url
        try:
            await self.page.goto(url, wait_until="domcontentloaded", timeout=30000)
        except Exception as error:
            return f"navigation error: {str(error)[:200]}"
        await self.settle()
        return "ok"

    async def click(self, aid: str) -> str:
        loc = self._locate(aid)
        try:
            async with self.page.expect_download(timeout=2500) as download_info:
                try:
                    await loc.click(timeout=8000)
                except Exception as error:
                    if "Timeout" in str(error):
                        await loc.dispatch_event("click")
                    else:
                        raise
            download = await download_info.value
            data = await self._read_download(download)
            return f"download {download.suggested_filename}:\n{data}"
        except Exception as error:
            if "expect_download" not in str(error) and "Timeout" not in str(error) and "download" not in str(error).lower():
                return f"click failed: {str(error)[:200]}"
        await self.settle()
        return "ok"

    async def type(self, aid: str, text: str, submit: bool = False) -> str:
        loc = self._locate(aid)
        try:
            await loc.fill(str(text), timeout=8000)
            if submit:
                await loc.press("Enter")
                await self.settle()
        except Exception as error:
            return f"type failed: {str(error)[:200]}"
        return "ok"

    async def select(self, aid: str, option: str) -> str:
        loc = self._locate(aid)
        try:
            try:
                await loc.select_option(value=str(option), timeout=5000)
            except Exception:
                await loc.select_option(label=str(option), timeout=5000)
        except Exception as error:
            return f"select failed: {str(error)[:200]}"
        await self.settle()
        return "ok"

    async def check(self, aid: str, checked: bool = True) -> str:
        loc = self._locate(aid)
        try:
            await loc.set_checked(bool(checked), timeout=5000)
        except Exception as error:
            return f"check failed: {str(error)[:200]}"
        return "ok"

    async def back(self) -> str:
        try:
            await self.page.go_back(wait_until="domcontentloaded")
        except Exception as error:
            return f"back failed: {str(error)[:200]}"
        await self.settle()
        return "ok"

    async def fetch_document(self, url: str) -> str:
        """Read a document the model chose (a link's href): ZIP members, PDF text or plain text/HTML."""
        if url.startswith("/"):
            url = self.page.url.split("/", 3)[0] + "//" + self.page.url.split("/", 3)[2] + url
        elif not url.startswith("http"):
            url = self.page.url.rsplit("/", 1)[0] + "/" + url
        try:
            response = await self.page.context.request.get(url, timeout=30000)
        except Exception as error:
            return f"fetch failed: {str(error)[:200]}"
        body = await response.body()
        return f"HTTP {response.status} {response.headers.get('content-type', '')}\n" + decode_document(body, url)

    async def _read_download(self, download) -> str:
        path = await download.path()
        with open(path, "rb") as handle:
            return decode_document(handle.read(), download.suggested_filename)


def decode_document(data: bytes, name: str = "") -> str:
    """ZIP: every member decoded; PDF: its text; HTML: its text; else UTF-8."""
    if data[:2] == b"PK":
        out = []
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            for info in archive.infolist():
                if info.is_dir():
                    continue
                out.append(f"--- {info.filename} ---\n" + decode_document(archive.read(info), info.filename))
        return "\n".join(out)
    if data[:4] == b"%PDF":
        try:
            from pypdf import PdfReader
            reader = PdfReader(io.BytesIO(data))
            return "\n".join(page.extract_text() or "" for page in reader.pages)
        except Exception as error:
            return f"(pdf not readable: {error})"
    text = data.decode("utf-8", errors="replace")
    if "<html" in text[:2000].lower() or "<body" in text[:4000].lower():
        text = re.sub(r"<(script|style)[^>]*>.*?</\1>", " ", text, flags=re.S | re.I)
        text = re.sub(r"<br\s*/?>|</(p|div|tr|li|h\d)>", "\n", text, flags=re.I)
        text = re.sub(r"</t[dh]>", " | ", text, flags=re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        import html as _html
        text = _html.unescape(text)
        text = re.sub(r"[ \t]+", " ", text)
        text = re.sub(r"\n\s*\n+", "\n", text)
    return text.strip()

