def decode_document(data: bytes, name: str = "") -> str:
    """ZIP: every member decoded; PDF: its text; HTML: its text; else UTF-8."""
    if data[:2] == b"PK":
        out = []
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            for info in archive.infolist():
                if info.is_dir():
                    continue
                out.append(f"--- {info.filename} ---\n" + decode_document(archive.read(info), info.filename))
        return "\n".join(out)
    if data[:4] == b"%PDF":
        try:
            from pypdf import PdfReader
            reader = PdfReader(io.BytesIO(data))
            return "\n".join(page.extract_text() or "" for page in reader.pages)
        except Exception as error:
            return f"(pdf not readable: {error})"
    text = data.decode("utf-8", errors="replace")
    if "<html" in text[:2000].lower() or "<body" in text[:4000].lower():
        text = re.sub(r"<(script|style)[^>]*>.*?</\1>", " ", text, flags=re.S | re.I)
        text = re.sub(r"<br\s*/?>|</(p|div|tr|li|h\d)>", "\n", text, flags=re.I)
        text = re.sub(r"</t[dh]>", " | ", text, flags=re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        import html as _html
        text = _html.unescape(text)
        text = re.sub(r"[ \t]+", " ", text)
        text = re.sub(r"\n\s*\n+", "\n", text)
    return text.strip()

