toolUseResult.originalFile:
"""The model-driven browsing loop: the model sees the page, picks one tool call, sees the result, until it finishes.

Each investigator gets a browser, a goal and an answer schema. The model chooses every navigation, search and
document; the loop only executes its calls and keeps the context small (old page views are dropped).
"""
import asyncio
import json
import os
import re
import time

from openai import AsyncOpenAI

MODEL = os.environ.get("AGENT_MODEL", "qwen3.8-flash-next")
PAGE_LIMIT = 14000

_client = None


def client() -> AsyncOpenAI:
    global _client
    if _client is None:
        _client = AsyncOpenAI(base_url=os.environ["QWEN_BASE_URL"], api_key=os.environ["QWEN_API_KEY"], timeout=300,
                              max_retries=0)
    return _client


class Usage:
    calls = 0
    prompt = 0
    completion = 0


async def chat(messages, tools=None, temperature=0.2, max_tokens=4000, tool_choice=None):
    """One model call, retried on errors (hosted models can hiccup)."""
    last = None
    for attempt in range(6):
        try:
            kwargs = dict(model=MODEL, messages=messages, temperature=temperature, max_tokens=max_tokens)
            if tools:
                kwargs["tools"] = tools
                if tool_choice:
                    kwargs["tool_choice"] = tool_choice
            reply = await client().chat.completions.create(**kwargs)
            Usage.calls += 1
            if reply.usage:
                Usage.prompt += reply.usage.prompt_tokens or 0
                Usage.completion += reply.usage.completion_tokens or 0
            return reply.choices[0].message
        except Exception as error:  # noqa: BLE001
            last = error
            await asyncio.sleep(min(2 ** attempt, 20))
    raise RuntimeError(f"model call failed: {last}")


def tool(name, description, **params):
    required = [k for k, v in params.items() if not v.pop("optional", False)]
    return {"type": "function", "function": {"name": name, "description": description,
                                             "parameters": {"type": "object", "properties": params,
                                                            "required": required}}}


S = {"type": "string"}
BROWSER_TOOLS = [
    tool("goto", "Open a URL or a path on the current site (e.g. a link's href).", url=dict(S)),
    tool("click", "Click the element with this id from the page view (links, buttons, summaries, tabs).", id=dict(S)),
    tool("type", "Type text into an input (replaces its value). submit=true presses Enter afterwards.",
         id=dict(S), text=dict(S), submit={"type": "boolean", "optional": True}),
    tool("select", "Choose an option of a <select> by its value or label.", id=dict(S), option=dict(S)),
    tool("check", "Tick (true) or untick (false) a checkbox or radio button.", id=dict(S),
         checked={"type": "boolean"}),
    tool("close_popups", "Close open modal dialogs/popups that block the page."),
    tool("back", "Go back one page in the browser history."),
    tool("read_document", "Download and read a document (ZIP, PDF, text, HTML) by its link URL or path.", url=dict(S)),
    tool("page_more", "Show the next part of a long page view.", offset={"type": "integer"}),
    tool("note", "Save a finding to your notebook (kept for the rest of the task even when old pages are dropped). "
                 "Quote exact values, dates and sources.", text=dict(S)),
]


async def run_browser_task(name, browser, system, goal, finish_schema, max_steps=40, deadline=None, log=print,
                           extra_tools=None, extra_handlers=None):
    """Let the model work on one website until it calls finish(...) with its findings."""
    finish = tool("finish", "Finish the task and hand in your findings in this exact structure.",
                  result=finish_schema)
    tools = BROWSER_TOOLS + (extra_tools or []) + [finish]
    handlers = extra_handlers or {}
    notes = []
    messages = [{"role": "system", "content": system},
                {"role": "user", "content": goal}]
    view_offset = 0
    for step in range(max_steps):
        if deadline and time.time() > deadline:
            log(f"[{name}] deadline reached, asking for findings")
            break
        page = await browser.snapshot()
        chunk = page[view_offset:view_offset + PAGE_LIMIT]
        more = len(page) > view_offset + PAGE_LIMIT
        view = (f"CURRENT PAGE (chars {view_offset}-{view_offset + len(chunk)} of {len(page)}"
                f"{'; call page_more for the rest' if more else ''}):\n{chunk}")
        view_offset = 0
        if notes:
            view = "YOUR NOTEBOOK:\n" + "\n".join(f"- {n}" for n in notes) + "\n\n" + view
        # keep only the latest page view in context
        for m in messages:
            if m.get("role") == "user" and str(m.get("content")).startswith(("YOUR NOTEBOOK", "CURRENT PAGE")):
                m["content"] = "(old page view omitted)"
        messages.append({"role": "user", "content": view})
        reply = await chat(messages, tools=tools)
        calls = reply.tool_calls or []
        messages.append({"role": "assistant", "content": reply.content or "",
                         "tool_calls": [c.model_dump() for c in calls] if calls else None})
        if not calls:
            messages[-1].pop("tool_calls")
            messages.append({"role": "user", "content": "Use exactly one tool call per turn. Call finish when done."})
            continue
        for call in calls[:3]:
            fn = call.function.name
            try:
                args = json.loads(call.function.arguments or "{}")
            except ValueError:
                args = {}
            log(f"[{name}] {step}: {fn} {json.dumps(args, ensure_ascii=False)[:300]}")
            if fn == "finish":
                return args.get("result", args), notes
            result = await dispatch(browser, fn, args, notes, handlers)
            if fn == "page_more":
                view_offset = int(args.get("offset") or PAGE_LIMIT)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": str(result)[:30000]})
        for call in calls[3:]:
            messages.append({"role": "tool", "tool_call_id": call.id, "content": "skipped: one action per turn"})
    # out of steps or time: ask for the best findings so far
    messages.append({"role": "user", "content": "Stop browsing now. Call finish with everything you found so far; "
                                                "leave unknown fields null."})
    reply = await chat(messages, tools=[finish], tool_choice={"type": "function", "function": {"name": "finish"}})
    for call in reply.tool_calls or []:
        try:
            args = json.loads(call.function.arguments or "{}")
            return args.get("result", args), notes
        except ValueError:
            pass
    return None, notes


async def dispatch(browser, fn, args, notes, handlers):
    try:
        if fn in handlers:
            return await handlers[fn](**args)
        if fn == "goto":
