import os
import time
from dataclasses import dataclass

import httpx

from negotiator.telemetry import Recorder, log

DEFAULT_MODEL = "gpt-6-luna"


class DecisionError(RuntimeError):
    pass


@dataclass
class Choice:
    value: str
    probabilities: dict[str, float]
    confidence: float | None


class DecisionsClient:
    def __init__(self, recorder: Recorder | None = None) -> None:
        self.api_key = os.environ.get("OPENAI_API_KEY", "")
        if not self.api_key:
            raise ValueError("the Decisions API needs OPENAI_API_KEY in the environment or .env")
        self.model = os.environ.get("DECISIONS_MODEL", DEFAULT_MODEL)
        self.base_url = os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")
        self.timeout = float(os.environ.get("DECISIONS_TIMEOUT_S", "20"))
        self.recorder = recorder
        self.http = httpx.Client(
            timeout=self.timeout,
            headers={"Authorization": f"Bearer {self.api_key}", "Content-Type": "application/json"},
        )

    def describe(self) -> str:
        return f"openai-decisions:{self.model}"

    def choose(
        self,
        input_text: str,
        instructions: str,
        choices: list[dict],
        *,
        name: str = "choice",
        context: dict | None = None,
    ) -> Choice:
        """One `choice` question; `choices` are {"value", "description"}. Raises DecisionError on any failure."""
        body = {
            "model": self.model,
            "input": input_text,
            "questions": [{"type": "choice", "name": name, "instructions": instructions, "choices": choices}],
        }
