    lo,hi=0.0,(terms.get('unit_price') or 100)*3
    for _ in range(60):
        mid=(lo+hi)/2
        if total_cost(case,{**terms,'unit_price':mid})>target: hi=mid
        else: lo=mid
    return round(lo,3)
