import json, sys, statistics as st
from collections import defaultdict
D = json.load(open(sys.argv[1])); R = D["rows"]
def m(xs): xs=[x for x in xs if x is not None]; return (round(100*st.mean(xs),2), len(xs)) if xs else ("-",0)
print("ALL drop% mean", m([r["drop"] for r in R]))
print("\n-- drop by reply status"); 
for s in ("open","final_offer","agreed"): print(s, m([r["drop"] for r in R if r["status"]==s]))
print("\n-- drop by round"); 
for k in range(1,8): print(k, m([r["drop"] for r in R if r["round"]==k]))
print("\n-- by claim type present in our message (drop%, n)")
types=sorted({t for r in R for t in r["claims"]})
for t in types:
    w=[r["drop"] for r in R if t in r["claims"]]; wo=[r["drop"] for r in R if t not in r["claims"]]
    print(f"{t:16s} with {m(w)} without {m(wo)}")
print("\n-- by number of claims"); 
for k in range(0,5): print(k, m([r["drop"] for r in R if r["n_claims"]==k]))
print("\n-- by 'taken into account' count in reply"); 
for k in range(0,4): print(k, m([r["drop"] for r in R if r["taken"]==k]))
print("\n-- by 'does not change' count"); 
for k in range(0,3): print(k, m([r["drop"] for r in R if r["nochange"]==k]))
print("\n-- 'Which figures?' in reply", m([r["drop"] for r in R if r["figures_q"]]), "else", m([r["drop"] for r in R if not r["figures_q"]]))
print("\n-- gap (our ask under their price) buckets")
for lo,hi in ((-1,0.02),(0.02,0.05),(0.05,0.1),(0.1,0.15),(0.15,0.2),(0.2,0.3),(0.3,1)):
    sub=[r for r in R if r["gap"] is not None and lo<=r["gap"]<hi]
    fin=sum(r["status"]=="final_offer" for r in sub)
    print(f"[{lo:.2f},{hi:.2f}) drop {m([r['drop'] for r in sub])} final-rate {fin}/{len(sub)}")
print("\n-- questions in our message"); 
for k in range(0,3): print(k, m([r["drop"] for r in R if min(r["questions"],2)==k]))
print("\n-- words buckets")
for lo,hi in ((0,60),(60,120),(120,200),(200,2000)): print(lo,hi, m([r["drop"] for r in R if lo<=r["words"]<hi]))
EOF
